{
  "criteria": [
    {
      "id": "C1",
      "level": "Proficient",
      "mark": 4,
      "evidence": [
        {
          "where": "Question 1",
          "quote": "The two most important quality attributes are performance and availability, because the business depends on the lunch hour"
        },
        {
          "where": "Question 1",
          "quote": "Response measure: the system should stay up most of the time."
        }
      ],
      "reasoning": "Both attributes are relevant and justified with scenario details. The performance scenario has all six parts and measurable targets. The availability scenario also names the six parts, but its response measure, “most of the time,” is not measurable."
    },
    {
      "id": "C2",
      "level": "Excellent",
      "mark": 6,
      "evidence": [
        {
          "where": "Question 2",
          "quote": "Instead the existing application should be restructured into a modular monolith with clear internal modules"
        },
        {
          "where": "Question 2",
          "quote": "With five developers, running eight or ten services would mean more time spent on infrastructure than on features."
        },
        {
          "where": "Question 2",
          "quote": "The trade-off I accept is that modules cannot be scaled independently, and a bug in one module can still crash the whole process."
        }
      ],
      "reasoning": "The recommendation is clear and supported by scenario-specific trade-offs involving the small team, operational overhead, current performance and deployment problems. It also acknowledges concrete downsides of the modular monolith."
    },
    {
      "id": "C3",
      "level": "Developing",
      "mark": 3,
      "evidence": [
        {
          "where": "Question 3",
          "quote": "A = 0.9995 × 0.999 × 0.9995 × 0.995 = 0.99301"
        },
        {
          "where": "Question 3",
          "quote": "Downtime = (1 − 0.99301) × 720 = 0.00699 × 720 = 3.5 hours per month."
        },
        {
          "where": "Question 3",
          "quote": "So the new availability of placing an order is 99.9975%"
        }
      ],
      "reasoning": "Part (a) is correct. Part (b) has an arithmetic error: the downtime is about 5.0 hours, not 3.5. Part (c) gives payment-provider availability rather than end-to-end availability; including the other series components gives about 99.80% availability and 1.5 hours of monthly downtime."
    },
    {
      "id": "C4",
      "level": "Developing",
      "mark": 2,
      "evidence": [
        {
          "where": "Question 4",
          "quote": "When failures exceed a threshold (for example 50% of calls in 10 seconds) the breaker moves to Closed"
        },
        {
          "where": "Question 4",
          "quote": "If they succeed it opens again, otherwise it stays closed."
        }
      ],
      "reasoning": "The circuit breaker is an appropriate pattern, and fast failure and a threshold are discussed. However, the state transitions are reversed: normal calls pass in Closed, failures open the breaker, and successful Half-Open trials close it. The outage application is relevant, but this central mechanism error limits the answer."
    },
    {
      "id": "C5",
      "level": "Proficient",
      "mark": 3,
      "evidence": [
        {
          "where": "Question 5",
          "quote": "it is better to show a slightly stale menu from a cache (for example Redis with a 60-second TTL)"
        },
        {
          "where": "Question 5",
          "quote": "for payments we choose consistency and availability and give up partition tolerance."
        }
      ],
      "reasoning": "The availability choice for browsing and consistency preference for payment are reasonable, and Redis is a concrete browsing technique. CAP is misrepresented: during a partition, a system must trade consistency against availability, not give up partition tolerance. No concrete technique is named for the payment case."
    },
    {
      "id": "C6",
      "level": "Proficient",
      "mark": 3,
      "evidence": [
        {
          "where": "Question 6",
          "quote": "Context: After an order is paid, the application calls the outlet's tablet synchronously and waits for the reply."
        },
        {
          "where": "Question 6",
          "quote": "Decision: Publish an \"OrderPaid\" event to a durable message queue (RabbitMQ)."
        },
        {
          "where": "Question 6",
          "quote": "Consequences: Placing an order no longer waits for the outlet, so the response time improves."
        }
      ],
      "reasoning": "Context, decision and consequences are present and specific to the scenario. The consequences describe several benefits, but no negative consequence is stated, so the ADR is one-sided."
    },
    {
      "id": "C7",
      "level": "Proficient",
      "mark": 3,
      "evidence": [
        {
          "where": "Question 4",
          "quote": "The Circuit Breaker pattern [2] would have contained the failure."
        },
        {
          "where": "References",
          "quote": "[1] L. Bass, P. Clements, and R. Kazman, *Software Architecture in Practice*"
        }
      ],
      "reasoning": "The required headings and order are used, and the answers appear within the word limit. The reference list includes [1] but not cited source [2], and no assumptions are stated. These are citation and format problems."
    }
  ],
  "requirements": [
    {
      "id": "R1",
      "met": "partial",
      "where": "Question 1"
    },
    {
      "id": "R2",
      "met": "yes",
      "where": "Question 2"
    },
    {
      "id": "R3",
      "met": "partial",
      "where": "Question 3"
    },
    {
      "id": "R4",
      "met": "partial",
      "where": "Question 4"
    },
    {
      "id": "R5",
      "met": "partial",
      "where": "Question 5"
    },
    {
      "id": "R6",
      "met": "partial",
      "where": "Question 6"
    },
    {
      "id": "R7",
      "met": "partial",
      "where": "References"
    }
  ],
  "technical_issues": [
    {
      "where": "Question 3",
      "issue": "The downtime multiplication in part (b) is incorrect: 0.00699 × 720 is approximately 5.0 hours, not 3.5."
    },
    {
      "where": "Question 3",
      "issue": "Part (c) reports redundant payment availability as end-to-end availability. The other components remain in series, giving approximately 99.80% end-to-end availability and 1.5 hours of monthly downtime."
    },
    {
      "where": "Question 4",
      "issue": "Circuit breaker state transitions are inverted: Closed permits normal calls, failures move it to Open for fast failure, and successful Half-Open trials return it to Closed."
    },
    {
      "where": "Question 5",
      "issue": "CAP does not permit choosing consistency and availability while giving up partition tolerance; during a partition, consistency and availability must be traded off."
    },
    {
      "where": "Question 5",
      "issue": "No concrete technique is provided for the payment consistency choice."
    },
    {
      "where": "References",
      "issue": "Citation [2] has no corresponding reference-list entry, and the submission does not state assumptions."
    }
  ],
  "overall": "The submission gives a strong, scenario-specific architectural recommendation and mostly clear answers. Marks are reduced by two availability-calculation errors, reversed circuit-breaker states, an incorrect CAP explanation, and incomplete ADR consequences and citation/assumption requirements."
}
